def get_invoice(current_user: User, invoice_id: int, db: Database) -> Invoice:
    # Secure: filters by invoice_id and verifies tenant ownership
    invoice = db.query(Invoice).filter(
        Invoice.id == invoice_id,
        Invoice.tenant_id == current_user.tenant_id
    ).first()
    if not invoice:
        raise NotFoundError('Invoice not found or access denied')
    return invoice

