def search_users_by_email(email_query: str, db_connection) -> list[dict]:
    # Secure parameterized query with bound placeholder
    query = "SELECT id, username, email FROM users WHERE email LIKE %s"
    cursor = db_connection.cursor()
    cursor.execute(query, (f"%{email_query}%",))
    return cursor.fetchall()

