#include <MFRC522.h>
MFRC522 mfrc522(10, 9);
byte authorizedUID[] = {0xDE, 0xAD, 0xBE, 0xEF};

void loop() {
    if (!mfrc522.PICC_IsNewCardPresent() || !mfrc522.PICC_ReadCardSerial()) return;

    bool isAuthorized = true;
